source='''from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    counts = {"top_stem": 0, "bottom_stem": 0}
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    p = (y + dy, x + dx)
                    if 0 <= p[0] < h and 0 <= p[1] < w and grid[p[0]][p[1]] == 2 and p not in seen:
                        seen.add(p)
                        q.append(p)
            minr, maxr = min(y for y, x in cells), max(y for y, x in cells)
            row_counts = {y: sum(1 for yy, x in cells if yy == y) for y in range(minr, maxr + 1)}
            if row_counts[minr] == 1:
                counts["top_stem"] += 1
            elif row_counts[maxr] == 1:
                counts["bottom_stem"] += 1
    out = [[0] * 6 for _ in range(3)]
    for n, color, col0 in ((counts["top_stem"], 3, 0), (counts["bottom_stem"], 1, 3)):
        positions = ((0, 0), (0, 2), (2, 0), (2, 2))
        for i in range(min(n, 4)):
            y, x = positions[i]
            out[y][col0 + x] = color
    return out
'''
